INSERT INTO chatbot_qa (question, answer, category, keywords, priority) VALUES
('Qu''est-ce que SERVIO ?', 'SERVIO est une plateforme qui connecte les clients aux meilleurs prestataires de services. Vous pouvez trouver des artisans, consultants, créatifs et professionnels qualifiés près de chez vous ou à distance.', 'general', ARRAY['servio', 'plateforme', 'présentation', 'qu''est-ce', 'définition'], 10),
('Comment fonctionne SERVIO ?', 'SERVIO fonctionne simplement : 1) Recherchez un prestataire par catégorie ou localisation, 2) Consultez les profils et avis, 3) Réservez directement en ligne, 4) Communiquez via notre messagerie intégrée.', 'general', ARRAY['fonctionnement', 'comment', 'marche', 'utilisation', 'étape'], 10),
('SERVIO est-il gratuit ?', 'Oui, l''inscription et la recherche de prestataires sur SERVIO sont entièrement gratuits. Les prestataires paient une commission sur chaque réservation.', 'general', ARRAY['gratuit', 'prix', 'coût', 'tarif', 'abonnement'], 10),
('Dans quels pays SERVIO est-il disponible ?', 'SERVIO est disponible dans plusieurs pays francophones dont la France, le Cameroun, la Côte d''Ivoire, le Sénégal et d''autres pays d''Afrique de l''Ouest.', 'general', ARRAY['pays', 'disponible', 'localisation', 'géographie', 'région'], 5),
('Comment puis-je contacter le support ?', 'Vous pouvez nous contacter via le formulaire de contact sur notre site, par email à support@servio.com, ou via le chatbot disponible 24h/24 et 7j/7.', 'general', ARRAY['contact', 'support', 'aide', 'assistance', 'email'], 10),
('SERVIO est-il sécurisé ?', 'Oui, SERVIO utilise des paiements sécurisés, vérifie les profils des prestataires, et offre une protection contre les fraudes. Vos données personnelles sont protégées.', 'general', ARRAY['sécurité', 'sécurisé', 'protection', 'données', 'fraude'], 10),
('Puis-je annuler une réservation ?', 'Oui, vous pouvez annuler une réservation selon les conditions d''annulation du prestataire. Les remboursements sont traités selon la politique de chaque prestataire.', 'general', ARRAY['annuler', 'remboursement', 'cancellation', 'retour', 'politique'], 10),
('Comment puis-je laisser un avis ?', 'Après la completion d''un service, vous recevrez une notification pour laisser un avis. Vous pouvez noter le prestataire sur plusieurs critères et laisser un commentaire détaillé.', 'general', ARRAY['avis', 'notation', 'évaluation', 'commentaire', 'note'], 10),
('Les prestataires sont-ils vérifiés ?', 'Oui, tous les prestataires passent par un processus de vérification incluant l''identité, les qualifications et les références. Les profils vérifiés portent un badge.', 'general', ARRAY['vérifié', 'badge', 'authentique', 'qualité', 'confiance'], 10),
('Comment fonctionne le système de recommandation ?', 'Notre IA analyse vos besoins, vos préférences et votre historique pour vous recommander les prestataires les plus adaptés à votre projet.', 'general', ARRAY['recommandation', 'ia', 'algorithme', 'suggestion', 'personnalisation'], 5),
('Puis-je devenir prestataire sur SERVIO ?', 'Oui, inscrivez-vous comme prestataire, complétez votre profil avec vos services, tarifs et disponibilités. Après validation, vous pourrez recevoir des demandes de réservation.', 'general', ARRAY['prestataire', 'devenir', 'inscription', 'vendre', 'services'], 10),
('Quels types de services sont disponibles ?', 'SERVIO propose des services dans de nombreuses catégories : artisanat, conseil, beauté, informatique, événementiel, éducation, photographie, restauration, et bien d''autres.', 'general', ARRAY['catégorie', 'services', 'types', 'domaine', 'secteur'], 10),
('Comment SERVIO protège mes données ?', 'Nous utilisons le chiffrement SSL, respectons le RGPD, et ne partageons jamais vos données sans consentement. Vos informations sont stockées de manière sécurisée.', 'general', ARRAY['données', 'privé', 'confidentialité', 'rgpd', 'protection'], 10),
('Y a-t-il une application mobile ?', 'SERVIO est disponible en tant qu''application web progressive (PWA). Vous pouvez l''installer sur votre mobile depuis votre navigateur pour une expérience native.', 'general', ARRAY['mobile', 'application', 'app', 'pwa', 'téléphone'], 5),
('Comment fonctionne le paiement ?', 'Les paiements sont sécurisés via notre plateforme intégrée. Vous payez lors de la réservation et le prestataire reçoit le paiement après completion du service.', 'general', ARRAY['paiement', 'argent', 'transaction', 'sécurisé', 'carte'], 10),
('Puis-je discuter avec le prestataire avant de réserver ?', 'Oui, vous pouvez envoyer un message au prestataire via notre messagerie intégrée pour discuter de votre projet avant de réserver.', 'general', ARRAY['message', 'discuter', 'communication', 'avant', 'réservation'], 10),
('Comment fonctionne la géolocalisation ?', 'SERVIO utilise votre position pour trouver des prestataires près de chez vous. Vous pouvez également rechercher dans une ville ou région spécifique.', 'general', ARRAY['géolocalisation', 'position', 'près', 'localisation', 'carte'], 5),
('SERVIO propose-t-il des garanties ?', 'Oui, nous offrons une protection acheteur et une assurance sur certains services. Consultez les conditions pour plus de détails.', 'general', ARRAY['garantie', 'assurance', 'protection', 'risque', 'couverture'], 5),
('Comment puis-je signaler un problème ?', 'Si vous rencontrez un problème avec un prestataire ou un service, utilisez le bouton de signalement sur le profil ou contactez notre support.', 'general', ARRAY['signaler', 'problème', 'plainte', 'abus', 'réclamation'], 10),
('SERVIO est-il disponible en anglais ?', 'Actuellement, SERVIO est principalement disponible en français. Nous travaillons à ajouter d''autres langues à l''avenir.', 'general', ARRAY['anglais', 'langue', 'traduction', 'english', 'multilingue'], 5),
('Comment fonctionne la recherche ?', 'Utilisez la barre de recherche pour trouver des prestataires par mot-clé, catégorie ou localisation. Les résultats sont classés par pertinence et note.', 'general', ARRAY['recherche', 'trouver', 'chercher', 'moteur', 'résultats'], 10),
('Puis-je filtrer les résultats ?', 'Oui, utilisez les filtres de catégorie, prix, note, disponibilité et distance pour affiner votre recherche et trouver le prestataire idéal.', 'general', ARRAY['filtre', 'affiner', 'critères', 'catégorie', 'prix'], 10),
('Comment fonctionne le système d''avis ?', 'Les clients peuvent noter les prestataires sur plusieurs critères après chaque service. Les avis sont vérifiés pour assurer leur authenticité.', 'general', ARRAY['avis', 'notation', 'système', 'vérification', 'authenticité'], 10),
('Y a-t-il un programme de fidélité ?', 'Actuellement, SERVIO n''a pas de programme de fidélité. Nous travaillons à développer des avantages pour nos utilisateurs réguliers.', 'general', ARRAY['fidélité', 'programme', 'avantages', 'régulier', 'récompense'], 5),
('Comment fonctionne le chatbot ?', 'Notre chatbot IA est disponible 24/7 pour répondre à vos questions sur la plateforme, les réservations, les paiements et plus encore.', 'general', ARRAY['chatbot', 'ia', 'assistant', 'virtuel', '24/7'], 10),
('Puis-je utiliser SERVIO sans compte ?', 'Vous pouvez rechercher des prestataires sans compte, mais vous devez vous inscrire pour réserver un service ou contacter un prestataire.', 'general', ARRAY['sans compte', 'anonyme', 'recherche', 'inscription', 'obligatoire'], 5),
('Comment fonctionne le système de messagerie ?', 'Notre messagerie intégrée permet de communiquer directement avec les prestataires. Toutes les conversations sont sécurisées et privées.', 'general', ARRAY['messagerie', 'communication', 'intégrée', 'sécurisée', 'privée'], 10),
('Y a-t-il des frais cachés ?', 'Non, le prix affiché est le prix final. Aucun frais caché ni surprise à payer. La transparence est notre priorité.', 'general', ARRAY['frais', 'caché', 'surprise', 'transparence', 'final'], 10),
('Comment fonctionne la validation des profils ?', 'Les profils prestataires sont validés manuellement par notre équipe pour assurer la qualité et l''authenticité des prestataires.', 'general', ARRAY['validation', 'profil', 'qualité', 'authenticité', 'équipe'], 10),
('Puis-je faire une recherche avancée ?', 'Oui, utilisez les filtres avancés pour rechercher par catégorie, ville, prix, note, disponibilité et service à distance.', 'general', ARRAY['recherche avancée', 'filtre', 'critères', 'avancé', 'options'], 5),
('Comment fonctionne le système de signalement ?', 'Si vous rencontrez un problème, signalez-le via le bouton dédié. Notre équipe examinera chaque signalement et prendra les mesures nécessaires.', 'general', ARRAY['signalement', 'problème', 'équipe', 'mesures', 'examen'], 10),
('Y a-t-il une limite de recherche ?', 'Non, vous pouvez effectuer autant de recherches que vous le souhaitez. La plateforme est conçue pour vous aider à trouver le prestataire idéal.', 'general', ARRAY['limite', 'recherche', 'illimité', 'autant', 'vouloir'], 5),
('Comment fonctionne le système de classement ?', 'Les prestataires sont classés selon plusieurs critères : notes, nombre de réservations, taux de réponse, et mise en avant PRO.', 'general', ARRAY['classement', 'critères', 'notes', 'réservations', 'taux de réponse'], 10),
('Puis-je sauvegarder mes recherches ?', 'Vous pouvez ajouter des prestataires à vos favoris pour les retrouver facilement. Les favoris sont accessibles depuis votre compte.', 'general', ARRAY['sauvegarder', 'favoris', 'recherche', 'retrouver', 'facilement'], 5),
('Comment fonctionne le système de recommandation IA ?', 'Notre IA analyse vos besoins, vos préférences et votre historique pour vous recommander les prestataires les plus adaptés.', 'general', ARRAY['recommandation', 'ia', 'algorithme', 'personnalisation', 'besoins'], 10),
('Y a-t-il des fonctionnalités pour les entreprises ?', 'Oui, les entreprises peuvent créer un compte professionnel pour gérer plusieurs réservations et factures.', 'general', ARRAY['entreprise', 'professionnel', 'b2b', 'compte', 'fonctionnalités'], 5),
('Comment fonctionne le système de notifications ?', 'Vous recevez des notifications pour les nouvelles réservations, messages, rappels et mises à jour importantes.', 'general', ARRAY['notifications', 'alertes', 'rappels', 'mises à jour', 'importantes'], 10),
('Puis-je personnaliser mes préférences ?', 'Oui, allez dans les paramètres de votre compte pour personnaliser vos notifications, langue et préférences d''affichage.', 'general', ARRAY['personnaliser', 'préférences', 'paramètres', 'notifications', 'langue'], 5),
('Comment fonctionne le système de support ?', 'Notre support est disponible par email et via le chatbot. Pour les problèmes complexes, ouvrez un ticket de support.', 'general', ARRAY['support', 'email', 'chatbot', 'ticket', 'problème'], 10),
('Y a-t-il une FAQ détaillée ?', 'Oui, consultez notre page FAQ pour des réponses détaillées aux questions les plus fréquentes.', 'general', ARRAY['faq', 'questions fréquentes', 'détaillée', 'réponses', 'page'], 5),
('Comment fonctionne le système de mise en avant ?', 'Les prestataires PRO sont mis en avant dans les résultats de recherche pour plus de visibilité.', 'general', ARRAY['mise en avant', 'pro', 'visibilité', 'résultats', 'recherche'], 10),
('Puis-je voir les statistiques de ma recherche ?', 'Les statistiques de recherche sont disponibles dans votre compte pour suivre votre activité.', 'general', ARRAY['statistiques', 'recherche', 'compte', 'activité', 'suivre'], 5),
('Comment fonctionne le système de filtres ?', 'Les filtres permettent d''affiner votre recherche par catégorie, prix, note, disponibilité et distance.', 'general', ARRAY['filtres', 'affiner', 'recherche', 'catégorie', 'prix'], 10),
('Y a-t-il des tutoriels disponibles ?', 'Oui, consultez notre centre d''aide pour des tutoriels détaillés sur l''utilisation de la plateforme.', 'general', ARRAY['tutoriels', 'centre d''aide', 'utilisation', 'détaillés', 'guide'], 5),
('Comment fonctionne le système de comparaison ?', 'Vous pouvez comparer plusieurs prestataires en ajoutant à vos favoris et en consultant leurs profils côte à côte.', 'general', ARRAY['comparaison', 'prestataires', 'favoris', 'profils', 'côte à côte'], 10),
('Puis-je partager un profil ?', 'Oui, vous pouvez partager le lien d''un profil prestataire avec vos contacts via les réseaux sociaux ou email.', 'general', ARRAY['partager', 'profil', 'lien', 'réseaux sociaux', 'email'], 5),
('Comment fonctionne le système de recherche par catégorie ?', 'Sélectionnez une catégorie dans la liste pour voir tous les prestataires de cette catégorie.', 'general', ARRAY['catégorie', 'recherche', 'liste', 'prestataires', 'sélectionner'], 10),
('Y a-t-il une limite de favoris ?', 'Non, vous pouvez ajouter autant de prestataires à vos favoris que vous le souhaitez.', 'general', ARRAY['limite', 'favoris', 'autant', 'vouloir', 'illimité'], 5),
('Comment fonctionne le système de recherche par ville ?', 'Entrez une ville ou utilisez votre géolocalisation pour trouver des prestataires près de chez vous.', 'general', ARRAY['ville', 'recherche', 'géolocalisation', 'près', 'localisation'], 10),
('Puis-je rechercher par service à distance ?', 'Oui, activez le filtre "Service à distance" pour trouver des prestataires qui travaillent en ligne.', 'general', ARRAY['distance', 'remote', 'en ligne', 'filtre', 'service'], 5),
('Comment fonctionne le système de recherche par prix ?', 'Utilisez le filtre de prix pour trouver des prestataires dans votre budget.', 'general', ARRAY['prix', 'recherche', 'filtre', 'budget', 'coût'], 10),
('Y a-t-il des promotions disponibles ?', 'Les promotions sont disponibles ponctuellement. Abonnez-vous à notre newsletter pour être informé.', 'general', ARRAY['promotions', 'réductions', 'newsletter', 'informé', 'ponctuellement'], 5),
('Comment fonctionne le système de recherche par note ?', 'Utilisez le filtre de note pour trouver les prestataires les mieux notés.', 'general', ARRAY['note', 'recherche', 'filtre', 'notation', 'mieux notés'], 10),
('Puis-je voir l''historique de mes recherches ?', 'L''historique de recherche est disponible dans votre compte pour retrouver vos recherches précédentes.', 'general', ARRAY['historique', 'recherche', 'compte', 'précédentes', 'retrouver'], 5),
('Comment fonctionne le système de recherche par disponibilité ?', 'Utilisez le filtre de disponibilité pour trouver des prestataires disponibles immédiatement.', 'general', ARRAY['disponibilité', 'recherche', 'filtre', 'immédiat', 'créneau'], 10),
('Y a-t-il une application iOS ?', 'SERVIO est disponible en tant que PWA compatible avec iOS. Installez-la depuis Safari sur votre iPhone.', 'general', ARRAY['ios', 'iphone', 'safari', 'pwa', 'application'], 5),
('Comment fonctionne le système de recherche par mots-clés ?', 'Entrez des mots-clés dans la barre de recherche pour trouver des prestataires correspondants.', 'general', ARRAY['mots-clés', 'recherche', 'barre', 'correspondants', 'trouver'], 10),
('Puis-je utiliser SERVIO sur tablette ?', 'Oui, SERVIO est optimisé pour les tablettes et offre une expérience utilisateur fluide.', 'general', ARRAY['tablette', 'optimisé', 'expérience', 'fluide', 'utilisateur'], 5),
('Comment fonctionne le système de recherche par spécialité ?', 'Utilisez les filtres de catégorie et sous-catégorie pour trouver des prestataires spécialisés.', 'general', ARRAY['spécialité', 'recherche', 'filtre', 'catégorie', 'sous-catégorie'], 10),
('Y a-t-il une version desktop ?', 'Oui, SERVIO est entièrement accessible depuis n''importe quel navigateur sur ordinateur.', 'general', ARRAY['desktop', 'ordinateur', 'navigateur', 'accessible', 'version'], 5),
('Comment fonctionne le système de recherche par expérience ?', 'Les prestataires sont classés par expérience et nombre de réservations.', 'general', ARRAY['expérience', 'recherche', 'classement', 'réservations', 'nombre'], 10),
('Puis-je contacter plusieurs prestataires ?', 'Oui, vous pouvez contacter autant de prestataires que vous le souhaitez via la messagerie.', 'general', ARRAY['contacter', 'plusieurs', 'prestataires', 'messagerie', 'autant'], 5),
('Comment fonctionne le système de recherche par langue ?', 'Certains prestataires indiquent les langues parlées. Utilisez ce filtre si nécessaire.', 'general', ARRAY['langue', 'recherche', 'filtre', 'parlé', 'indiquent'], 10),
('Y a-t-il des guides disponibles ?', 'Oui, consultez notre centre d''aide pour des guides détaillés sur l''utilisation de la plateforme.', 'general', ARRAY['guides', 'centre d''aide', 'détaillés', 'utilisation', 'plateforme'], 5);
INSERT INTO chatbot_qa (question, answer, category, keywords, priority) VALUES
('Comment réserver un service ?', 'Pour réserver : 1) Trouvez un prestataire, 2) Cliquez sur "Réserver", 3) Choisissez date/heure, 4) Confirmez et payez. Vous recevrez une confirmation par email.', 'booking', ARRAY['réserver', 'booking', 'réservation', 'comment', 'processus'], 10),
('Puis-je modifier ma réservation ?', 'Les modifications de réservation dépendent du prestataire. Contactez-le via la messagerie pour demander un changement de date ou d''heure.', 'booking', ARRAY['modifier', 'changer', 'date', 'heure', 'modification'], 10),
('Que se passe-t-il si le prestataire annule ?', 'Si le prestataire annule, vous serez remboursé intégralement. Nous vous aiderons à trouver un autre prestataire si nécessaire.', 'booking', ARRAY['annulation', 'prestataire', 'remboursement', 'problème', 'solution'], 10),
('Comment voir mes réservations ?', 'Connectez-vous à votre compte et allez dans la section "Mes réservations" pour voir toutes vos réservations actuelles et passées.', 'booking', ARRAY['réservations', 'mes', 'historique', 'voir', 'compte'], 10),
('Puis-je réserver pour quelqu''un d''autre ?', 'Oui, vous pouvez réserver un service pour une autre personne. Indiquez simplement les informations du bénéficiaire lors de la réservation.', 'booking', ARRAY['autre', 'personne', 'tiers', 'cadeau', 'bénéficiaire'], 5),
('Y a-t-il des frais de réservation ?', 'SERVIO ne facture pas de frais de réservation aux clients. Vous payez uniquement le prix du service indiqué par le prestataire.', 'booking', ARRAY['frais', 'coût', 'réservation', 'supplément', 'commission'], 10),
('Comment confirmer une réservation ?', 'Après avoir choisi date/heure et payé, votre réservation est automatiquement confirmée. Vous recevrez un email de confirmation avec tous les détails.', 'booking', ARRAY['confirmer', 'confirmation', 'email', 'détails', 'validation'], 10),
('Puis-je réserver plusieurs services ?', 'Oui, vous pouvez réserver autant de services que vous le souhaitez avec différents prestataires.', 'booking', ARRAY['plusieurs', 'multiple', 'services', 'prestataires', 'différents'], 5),
('Comment fonctionne le calendrier de réservation ?', 'Le calendrier affiche les disponibilités du prestataire en temps réel. Sélectionnez une date et une heure créneau pour réserver.', 'booking', ARRAY['calendrier', 'disponibilité', 'créneau', 'horaire', 'planning'], 10),
('Puis-je réserver en urgence ?', 'Certains prestataires proposent des créneaux d''urgence. Filtrez votre recherche par "disponible immédiatement" pour les trouver.', 'booking', ARRAY['urgence', 'immédiat', 'rapide', 'dernière minute', 'urgent'], 5),
('Comment fonctionne le rappel de réservation ?', 'Vous recevrez des rappels par email et notification 24h avant votre réservation pour ne pas l''oublier.', 'booking', ARRAY['rappel', 'notification', 'email', 'avant', 'oubli'], 5),
('Puis-je réserver un service récurrent ?', 'Pour les services récurrents, contactez directement le prestataire via la messagerie pour organiser un abonnement ou des réservations multiples.', 'booking', ARRAY['récurrent', 'abonnement', 'régulier', 'mensuel', 'périodique'], 5),
('Comment annuler une réservation en cours ?', 'Allez dans "Mes réservations", sélectionnez la réservation et cliquez sur "Annuler". Suivez les instructions selon la politique du prestataire.', 'booking', ARRAY['annuler', 'en cours', 'mes réservations', 'bouton', 'instructions'], 10),
('Y a-t-il une limite de réservation ?', 'Non, il n''y a pas de limite au nombre de réservations que vous pouvez effectuer.', 'booking', ARRAY['limite', 'maximum', 'nombre', 'restriction', 'illimité'], 5),
('Comment fonctionne la validation de réservation ?', 'La réservation est validée dès le paiement. Le prestataire reçoit alors une notification et confirmera sa disponibilité.', 'booking', ARRAY['validation', 'paiement', 'notification', 'prestataire', 'confirmation'], 10),
('Puis-je réserver sans compte ?', 'Non, vous devez créer un compte pour réserver un service. Cela garantit la sécurité et permet le suivi de vos réservations.', 'booking', ARRAY['sans compte', 'anonyme', 'inscription', 'obligatoire', 'sécurité'], 10),
('Comment réserver un service spécifique ?', 'Utilisez la barre de recherche pour trouver le service souhaité, puis filtrez par catégorie, localisation et prix pour trouver le prestataire idéal.', 'booking', ARRAY['spécifique', 'recherche', 'filtre', 'catégorie', 'prix'], 10),
('Puis-je réserver pour une entreprise ?', 'Oui, les entreprises peuvent créer un compte professionnel et réserver des services pour leurs besoins.', 'booking', ARRAY['entreprise', 'professionnel', 'b2b', 'société', 'corporate'], 5),
('Comment fonctionne le suivi de réservation ?', 'Suivez l''état de votre réservation dans "Mes réservations" : en attente, confirmé, en cours, terminé, annulé.', 'booking', ARRAY['suivi', 'état', 'statut', 'mes réservations', 'avancement'], 10),
('Puis-je ajouter des notes à ma réservation ?', 'Oui, lors de la réservation, vous pouvez ajouter des notes pour le prestataire concernant vos besoins ou préférences.', 'booking', ARRAY['notes', 'commentaires', 'préférences', 'besoins', 'détails'], 5),
('Comment fonctionne le système de réservation ?', 'Notre système de réservation est simple et sécurisé. Sélectionnez un prestataire, choisissez un créneau, et payez en ligne.', 'booking', ARRAY['système', 'réservation', 'simple', 'sécurisé', 'en ligne'], 10),
('Puis-je réserver à l''avance ?', 'Oui, vous pouvez réserver à l''avance selon les disponibilités du prestataire. Certains prestataires acceptent les réservations plusieurs semaines à l''avance.', 'booking', ARRAY['à l''avance', 'semaines', 'disponibilités', 'prévoir', 'planifier'], 5),
('Comment fonctionne le paiement de réservation ?', 'Le paiement est effectué lors de la confirmation de réservation via notre plateforme sécurisée.', 'booking', ARRAY['paiement', 'réservation', 'confirmation', 'sécurisée', 'plateforme'], 10),
('Puis-je réserver pour un groupe ?', 'Oui, certains prestataires acceptent les réservations de groupe. Contactez-les via la messagerie pour organiser.', 'booking', ARRAY['groupe', 'plusieurs personnes', 'collectif', 'équipe', 'organiser'], 5),
('Comment fonctionne la confirmation de réservation ?', 'Vous recevrez une confirmation par email avec tous les détails de votre réservation.', 'booking', ARRAY['confirmation', 'email', 'détails', 'réservation', 'recevoir'], 10),
('Puis-je réserver un service sur mesure ?', 'Oui, contactez le prestataire via la messagerie pour discuter d''un service sur mesure personnalisé.', 'booking', ARRAY['sur mesure', 'personnalisé', 'custom', 'messagerie', 'discuter'], 5),
('Comment fonctionne l''annulation de réservation ?', 'L''annulation dépend de la politique du prestataire. Consultez les conditions avant d''annuler.', 'booking', ARRAY['annulation', 'politique', 'conditions', 'prestataire', 'dépend'], 10),
('Puis-je réserver un service d''essai ?', 'Certains prestataires proposent des services d''essai. Consultez leur profil pour voir si cette option est disponible.', 'booking', ARRAY['essai', 'test', 'premier', 'disponible', 'profil'], 5),
('Comment fonctionne le rappel de réservation ?', 'Vous recevrez des rappels automatiques avant votre réservation par email et notification.', 'booking', ARRAY['rappel', 'automatique', 'email', 'notification', 'avant'], 10),
('Puis-je réserver un service package ?', 'Oui, certains prestataires proposent des packages avec plusieurs services. Consultez leur profil pour les offres disponibles.', 'booking', ARRAY['package', 'offre', 'plusieurs services', 'bundle', 'profil'], 5),
('Comment fonctionne la modification de réservation ?', 'Contactez le prestataire via la messagerie pour demander une modification de date ou d''heure.', 'booking', ARRAY['modification', 'changer', 'date', 'heure', 'messagerie'], 10),
('Puis-je réserver un service virtuel ?', 'Oui, activez le filtre "Service à distance" pour trouver des prestataires qui travaillent en ligne.', 'booking', ARRAY['virtuel', 'en ligne', 'distance', 'remote', 'filtre'], 5),
('Comment fonctionne le remboursement de réservation ?', 'Le remboursement dépend de la politique d''annulation du prestataire. Contactez le support en cas de problème.', 'booking', ARRAY['remboursement', 'annulation', 'politique', 'support', 'problème'], 10),
('Puis-je réserver un service de consultation ?', 'Oui, de nombreux prestataires proposent des services de consultation. Filtrez par catégorie "Conseil".', 'booking', ARRAY['consultation', 'conseil', 'catégorie', 'filtre', 'service'], 5),
