INSERT INTO chatbot_qa (question, answer, category, keywords, priority) VALUES
('Quels moyens de paiement sont acceptés ?', 'Nous acceptons les cartes bancaires (Visa, Mastercard), PayPal, et les paiements mobiles selon votre pays.', 'payment', ARRAY['paiement', 'carte', 'visa', 'mastercard', 'paypal'], 10),
