INSERT INTO chatbot_qa (question, answer, category, keywords, priority) VALUES
('Comment créer un compte ?', 'Cliquez sur "S''inscrire" en haut de la page, remplissez vos informations (nom, email, mot de passe), et validez votre email pour activer votre compte.', 'account', ARRAY['créer', 'compte', 'inscrire', 'inscription', 'email'], 10),
('J''ai oublié mon mot de passe', 'Cliquez sur "Mot de passe oublié" sur la page de connexion. Entrez votre email et suivez les instructions pour réinitialiser votre mot de passe.', 'account', ARRAY['oublié', 'mot de passe', 'réinitialiser', 'connexion', 'email'], 10),
('Comment modifier mon profil ?', 'Connectez-vous et allez dans "Mon profil" pour modifier vos informations personnelles, photo et préférences.', 'account', ARRAY['modifier', 'profil', 'informations', 'photo', 'préférences'], 10),
('Comment supprimer mon compte ?', 'Pour supprimer votre compte, allez dans "Paramètres" > "Supprimer le compte". Notez que cette action est irréversible.', 'account', ARRAY['supprimer', 'compte', 'paramètres', 'irréversible', 'désinscription'], 10),
('Puis-je avoir plusieurs comptes ?', 'Non, une personne ne peut avoir qu''un seul compte. Créer plusieurs comptes est contraire à nos conditions d''utilisation.', 'account', ARRAY['plusieurs', 'comptes', 'multiple', 'conditions', 'utilisation'], 5),
('Comment changer mon email ?', 'Allez dans "Paramètres" > "Informations personnelles" pour changer votre email. Vous devrez valider la nouvelle adresse.', 'account', ARRAY['changer', 'email', 'paramètres', 'valider', 'adresse'], 10),
('Comment changer mon mot de passe ?', 'Allez dans "Paramètres" > "Sécurité" > "Changer le mot de passe". Entrez votre ancien et nouveau mot de passe.', 'account', ARRAY['changer', 'mot de passe', 'sécurité', 'paramètres', 'nouveau'], 10),
('Comment activer la 2FA ?', 'La double authentification (2FA) peut être activée dans "Paramètres" > "Sécurité" pour protéger votre compte.', 'account', ARRAY['2fa', 'double authentification', 'sécurité', 'activer', 'protection'], 5),
