INSERT INTO chatbot_qa (question, answer, category, keywords, priority) VALUES
('Comment devenir prestataire ?', 'Pour devenir prestataire, créez un compte et cliquez sur "Devenir prestataire" dans votre tableau de bord. Complétez votre profil et vos services.', 'provider', ARRAY['devenir', 'prestataire', 'compte', 'tableau de bord', 'profil'], 10),
('Quels sont les frais pour les prestataires ?', 'Les prestataires paient une commission de 15% sur chaque réservation. Le compte PRO réduit cette commission à 10%.', 'provider', ARRAY['frais', 'commission', 'prestataire', '15%', 'pro'], 10),
('Comment ajouter mes services ?', 'Allez dans "Mon profil" > "Services" pour ajouter et décrire vos services avec vos tarifs.', 'provider', ARRAY['ajouter', 'services', 'profil', 'tarifs', 'décrire'], 10),
('Comment modifier mes tarifs ?', 'Modifiez vos tarifs dans "Mon profil" > "Services" pour chaque service proposé.', 'provider', ARRAY['modifier', 'tarifs', 'profil', 'services', 'changer'], 10),
('Puis-je avoir plusieurs services ?', 'Oui, vous pouvez proposer autant de services que vous le souhaitez.', 'provider', ARRAY['plusieurs', 'services', 'proposer', 'autant', 'souhaité'], 5),
('Comment fonctionne le calendrier ?', 'Votre calendrier est disponible dans "Mon profil" > "Calendrier" pour gérer vos disponibilités.', 'provider', ARRAY['calendrier', 'profil', 'disponibilités', 'gérer', 'planning'], 10),
('Puis-je bloquer des dates ?', 'Oui, bloquez des dates dans votre calendrier pour indiquer vos indisponibilités.', 'provider', ARRAY['bloquer', 'dates', 'calendrier', 'indisponibilités', 'planning'], 10),
('Comment recevoir les paiements ?', 'Les paiements sont transférés sur votre compte bancaire enregistré. Le délai est de 7 jours ouvrés.', 'provider', ARRAY['paiements', 'recevoir', 'bancaire', '7 jours', 'transfert'], 10),
('Puis-je changer mes horaires ?', 'Oui, modifiez vos horaires dans "Mon profil" > "Horaires" pour définir vos créneaux disponibles.', 'provider', ARRAY['changer', 'horaires', 'profil', 'créneaux', 'disponibles'], 10),
('Comment fonctionne la mise en avant ?', 'Les prestataires PRO sont mis en avant dans les résultats de recherche pour plus de visibilité.', 'provider', ARRAY['mise en avant', 'pro', 'résultats', 'visibilité', 'recherche'], 10),
('Puis-je ajouter des photos ?', 'Oui, ajoutez des photos de vos travaux dans "Mon profil" > "Galerie" pour présenter votre savoir-faire.', 'provider', ARRAY['photos', 'ajouter', 'profil', 'galerie', 'travaux'], 10),
('Comment fonctionne la notation ?', 'Les clients peuvent noter les prestataires après chaque réservation. La note moyenne est affichée sur votre profil.', 'provider', ARRAY['notation', 'note', 'clients', 'réservation', 'moyenne'], 10),
('Puis-je répondre aux avis ?', 'Oui, répondez aux avis dans "Mon profil" > "Avis" pour interagir avec vos clients.', 'provider', ARRAY['répondre', 'avis', 'profil', 'clients', 'interagir'], 10),
('Comment fonctionne la vérification ?', 'La vérification nécessite une pièce d''identité et des justificatifs professionnels. Elle augmente votre crédibilité.', 'provider', ARRAY['vérification', 'identité', 'justificatifs', 'crédibilité', 'professionnels'], 10),
('Puis-je avoir une zone de service ?', 'Oui, définissez votre zone de service dans "Mon profil" > "Localisation" pour limiter vos déplacements.', 'provider', ARRAY['zone', 'service', 'profil', 'localisation', 'déplacements'], 10),
('Comment fonctionne le profil PRO ?', 'Le profil PRO offre une commission réduite, une mise en avant et un support prioritaire.', 'provider', ARRAY['profil pro', 'commission', 'mise en avant', 'support', 'prioritaire'], 10),
('Puis-je annuler une réservation ?', 'Oui, vous pouvez annuler une réservation depuis votre tableau de bord. Respectez notre politique d''annulation.', 'provider', ARRAY['annuler', 'réservation', 'tableau de bord', 'politique', 'annulation'], 10),
('Comment fonctionne la messagerie ?', 'Utilisez la messagerie pour communiquer avec vos clients avant et après les réservations.', 'provider', ARRAY['messagerie', 'communiquer', 'clients', 'réservations', 'avant'], 10),
('Puis-je avoir un portfolio ?', 'Oui, créez un portfolio dans "Mon profil" > "Portfolio" pour montrer vos réalisations.', 'provider', ARRAY['portfolio', 'profil', 'réalisations', 'montrer', 'créer'], 10),
('Comment fonctionne la recherche de clients ?', 'Les clients vous trouvent via la recherche. Optimisez votre profil avec des mots-clés pertinents.', 'provider', ARRAY['recherche', 'clients', 'profil', 'mots-clés', 'optimiser'], 10),
('Puis-je ajouter une description ?', 'Oui, ajoutez une description détaillée dans "Mon profil" > "Description" pour vous présenter.', 'provider', ARRAY['description', 'ajouter', 'profil', 'présenter', 'détaillée'], 10),
('Comment fonctionne la commission ?', 'La commission est prélevée sur chaque réservation. Elle est de 15% pour les comptes standards et 10% pour les comptes PRO.', 'provider', ARRAY['commission', 'prélevée', 'réservation', '15%', '10%'], 10),
