INSERT INTO chatbot_qa (question, answer, category, keywords, priority) VALUES
('Comment contacter le support ?', 'Contactez le support via le formulaire de contact, par email à support@exemple.com ou via le chat en direct.', 'support', ARRAY['contacter', 'support', 'email', 'chat', 'direct'], 10),
('Quels sont les horaires du support ?', 'Le support est disponible du lundi au vendredi de 9h à 18h. Le support PRO est disponible 24/7.', 'support', ARRAY['horaires', 'support', 'lundi', 'vendredi', '9h-18h'], 10),
('Comment fonctionne le chat en direct ?', 'Le chat en direct est accessible en bas à droite de l''écran pendant les heures ouvrées.', 'support', ARRAY['chat', 'direct', 'accessible', 'heures ouvrées', 'bas'], 10),
('Puis-je avoir un appel téléphonique ?', 'Oui, demandez un rappel via le formulaire de contact. Un agent vous rappellera dans les 24h.', 'support', ARRAY['appel', 'téléphonique', 'rappel', '24h', 'agent'], 10),
('Comment fonctionne le centre d''aide ?', 'Le centre d''aide contient des articles et tutoriels pour vous aider à utiliser la plateforme.', 'support', ARRAY['centre d''aide', 'articles', 'tutoriels', 'utiliser', 'plateforme'], 10),
('Puis-je avoir une assistance en français ?', 'Oui, notre support est disponible en français et en plusieurs autres langues.', 'support', ARRAY['assistance', 'français', 'langues', 'disponible', 'multilingue'], 10),
('Comment fonctionne le ticket de support ?', 'Chaque demande de support crée un ticket unique. Vous pouvez suivre son avancement dans "Mes tickets".', 'support', ARRAY['ticket', 'support', 'unique', 'suivre', 'avancement'], 10),
