INSERT INTO chatbot_qa (question, answer, category, keywords, priority) VALUES
('Comment fonctionne la sécurité des données ?', 'Vos données sont chiffrées avec AES-256 et stockées sur des serveurs sécurisés.', 'security', ARRAY['sécurité', 'données', 'chiffrées', 'aes-256', 'serveurs'], 10),
('Puis-je activer la 2FA ?', 'Oui, activez la double authentification dans "Paramètres" > "Sécurité" pour protéger votre compte.', 'security', ARRAY['2fa', 'double authentification', 'paramètres', 'sécurité', 'protéger'], 10),
('Comment fonctionne le chiffrement ?', 'Nous utilisons le chiffrement SSL/TLS pour toutes les communications et AES-256 pour le stockage.', 'security', ARRAY['chiffrement', 'ssl', 'tls', 'aes-256', 'stockage'], 10),
('Puis-je voir mes connexions ?', 'Oui, consultez "Sécurité" > "Historique des connexions" pour voir les appareils connectés.', 'security', ARRAY['connexions', 'voir', 'sécurité', 'appareils', 'historique'], 10),
('Comment fonctionne la protection contre le phishing ?', 'Nous éduquons les utilisateurs et surveillons les tentatives de phishing.', 'security', ARRAY['protection', 'phishing', 'surveillance', 'tentatives', 'éduquer'], 10),
('Puis-je bloquer un appareil ?', 'Oui, révoquez l''accès d''un appareil dans "Sécurité" > "Appareils connectés".', 'security', ARRAY['bloquer', 'appareil', 'révoquer', 'accès', 'sécurité'], 10),
('Comment fonctionne la sécurité des mots de passe ?', 'Les mots de passe sont hachés avec bcrypt et jamais stockés en clair.', 'security', ARRAY['sécurité', 'mots de passe', 'hachés', 'bcrypt', 'clair'], 10),
('Puis-je avoir un mot de passe fort ?', 'Oui, utilisez un mot de passe d''au moins 8 caractères avec lettres, chiffres et symboles.', 'security', ARRAY['mot de passe', 'fort', '8 caractères', 'lettres', 'chiffres'], 10),
('Comment fonctionne la sécurité des paiements ?', 'Les paiements sont sécurisés avec Stripe et PCI-DSS compliant.', 'security', ARRAY['sécurité', 'paiements', 'stripe', 'pci-dss', 'compliant'], 10),
('Puis-je avoir une alerte de sécurité ?', 'Oui, vous recevez des alertes par email en cas d''activité suspecte.', 'security', ARRAY['alerte', 'sécurité', 'email', 'activité', 'suspecte'], 10),
('Comment fonctionne la conformité RGPD ?', 'Nous sommes conformes au RGPD et respectons vos droits sur vos données.', 'security', ARRAY['conformité', 'rgpd', 'droits', 'données', 'respectons'], 10),
('Puis-je exporter mes données ?', 'Oui, demandez l''export de vos données dans "Paramètres" > "Confidentialité".', 'security', ARRAY['exporter', 'données', 'paramètres', 'confidentialité', 'rgpd'], 10),
('Comment fonctionne la sécurité des sessions ?', 'Les sessions utilisent des tokens JWT sécurisés et expirent après inactivité.', 'security', ARRAY['sécurité', 'sessions', 'tokens', 'jwt', 'expirent'], 10),
('Puis-je avoir une connexion sécurisée ?', 'Oui, toutes les connexions utilisent HTTPS avec certificat SSL valide.', 'security', ARRAY['connexion', 'sécurisée', 'https', 'ssl', 'certificat'], 10),
('Comment fonctionne la sécurité des fichiers ?', 'Les fichiers uploadés sont scannés et stockés avec chiffrement.', 'security', ARRAY['sécurité', 'fichiers', 'scannés', 'chiffrement', 'stockés'], 10),
('Puis-je avoir une protection DDoS ?', 'Oui, nous utilisons Cloudflare pour protéger contre les attaques DDoS.', 'security', ARRAY['protection', 'ddos', 'cloudflare', 'attaques', 'protéger'], 10),
('Comment fonctionne la sécurité des API ?', 'L''API utilise des clés API, un taux limité et OAuth2 pour l''authentification.', 'security', ARRAY['sécurité', 'api', 'clés', 'taux limité', 'oauth2'], 10),
('Puis-je avoir une authentification forte ?', 'Oui, utilisez la 2FA pour une authentification forte de votre compte.', 'security', ARRAY['authentification', 'forte', '2fa', 'compte', 'sécurité'], 10),
('Comment fonctionne la sécurité des cookies ?', 'Les cookies utilisent SameSite Strict, Secure et HttpOnly.', 'security', ARRAY['sécurité', 'cookies', 'samesite', 'secure', 'httponly'], 10),
('Puis-je avoir une surveillance 24/7 ?', 'Oui, notre équipe de sécurité surveille la plateforme 24h/24 et 7j/7.', 'security', ARRAY['surveillance', '24/7', 'sécurité', 'équipe', 'plateforme'], 10),
('Comment fonctionne la sécurité des communications ?', 'Toutes les communications sont chiffrées de bout en bout.', 'security', ARRAY['sécurité', 'communications', 'chiffrées', 'bout en bout', 'protégées'], 10),
('Puis-je avoir une protection contre les malwares ?', 'Oui, tous les fichiers uploadés sont scannés pour détecter les malwares.', 'security', ARRAY['protection', 'malwares', 'fichiers', 'scannés', 'détecter'], 10),
('Comment fonctionne la sécurité des serveurs ?', 'Nos serveurs sont hébergés dans des datacenters certifiés ISO 27001.', 'security', ARRAY['sécurité', 'serveurs', 'datacenters', 'iso 27001', 'certifiés'], 10),
('Puis-je avoir une protection des données ?', 'Oui, vos données sont protégées par chiffrement et des contrôles d''accès stricts.', 'security', ARRAY['protection', 'données', 'chiffrement', 'accès', 'stricts'], 10),
('Comment fonctionne la sécurité des transactions ?', 'Les transactions sont sécurisées avec un chiffrement de bout en bout et une surveillance en temps réel.', 'security', ARRAY['sécurité', 'transactions', 'chiffrement', 'surveillance', 'temps réel'], 10),
('Puis-je avoir une authentification biométrique ?', 'Oui, l''authentification biométrique est disponible sur l''application mobile.', 'security', ARRAY['authentification', 'biométrique', 'mobile', 'application', 'disponible'], 10),
('Comment fonctionne la sécurité des emails ?', 'Les emails sont signés numériquement avec DKIM et SPF pour prévenir le phishing.', 'security', ARRAY['sécurité', 'emails', 'dkim', 'spf', 'phishing'], 10),
('Puis-je avoir une protection de la vie privée ?', 'Oui, nous respectons votre vie privée et ne partageons pas vos données.', 'security', ARRAY['protection', 'vie privée', 'données', 'partager', 'respectons'], 10),
('Comment fonctionne la sécurité des applications ?', 'Nos applications sont régulièrement auditées et testées pour les vulnérabilités.', 'security', ARRAY['sécurité', 'applications', 'auditées', 'testées', 'vulnérabilités'], 10),
('Puis-je avoir une protection contre les injections SQL ?', 'Oui, nous utilisons des requêtes paramétrées pour prévenir les injections SQL.', 'security', ARRAY['protection', 'injections sql', 'requêtes', 'paramétrées', 'prévenir'], 10),
('Comment fonctionne la sécurité des bases de données ?', 'Les bases de données sont chiffrées au repos et accessibles uniquement via VPN.', 'security', ARRAY['sécurité', 'bases de données', 'chiffrées', 'vpn', 'accès'], 10),
('Puis-je avoir une protection XSS ?', 'Oui, nous utilisons des politiques CSP et l''échappement des données pour prévenir XSS.', 'security', ARRAY['protection', 'xss', 'csp', 'échappement', 'données'], 10),
('Comment fonctionne la sécurité des réseaux ?', 'Nos réseaux sont segmentés et protégés par des firewalls de nouvelle génération.', 'security', ARRAY['sécurité', 'réseaux', 'segmentés', 'firewalls', 'protégés'], 10),
('Puis-je avoir une protection CSRF ?', 'Oui, nous utilisons des tokens CSRF pour prévenir les attaques CSRF.', 'security', ARRAY['protection', 'csrf', 'tokens', 'attaques', 'prévenir'], 10),
('Comment fonctionne la sécurité des backups ?', 'Les backups sont chiffrés et stockés dans plusieurs localisations géographiques.', 'security', ARRAY['sécurité', 'backups', 'chiffrés', 'localisations', 'géographiques'], 10),
('Puis-je avoir une protection des logs ?', 'Oui, les logs sont chiffrés et conservés uniquement pour la durée légale.', 'security', ARRAY['protection', 'logs', 'chiffrés', 'conservés', 'légale'], 10),
('Comment fonctionne la sécurité des identités ?', 'Nous utilisons OAuth2 et OpenID Connect pour une gestion sécurisée des identités.', 'security', ARRAY['sécurité', 'identités', 'oauth2', 'openid', 'connect'], 10),
('Puis-je avoir une protection des certificats ?', 'Oui, nos certificats SSL sont gérés automatiquement et renouvelés avant expiration.', 'security', ARRAY['protection', 'certificats', 'ssl', 'automatiquement', 'renouvelés'], 10),
('Comment fonctionne la sécurité des accès ?', 'L''accès aux données est basé sur le principe du moindre privilège.', 'security', ARRAY['sécurité', 'accès', 'principe', 'moindre privilège', 'basé'], 10),
('Puis-je avoir une protection des secrets ?', 'Oui, les secrets sont stockés dans un coffre-fort sécurisé et rotatifs.', 'security', ARRAY['protection', 'secrets', 'coffre-fort', 'sécurisé', 'rotatifs'], 10),
('Comment fonctionne la sécurité des audits ?', 'Nous réalisons des audits de sécurité réguliers avec des tiers indépendants.', 'security', ARRAY['sécurité', 'audits', 'réguliers', 'tiers', 'indépendants'], 10),
('Puis-je avoir une protection des dépendances ?', 'Oui, nous scannons régulièrement nos dépendances pour les vulnérabilités connues.', 'security', ARRAY['protection', 'dépendances', 'scannons', 'vulnérabilités', 'connues'], 10),
('Comment fonctionne la sécurité des tests ?', 'Nous effectuons des tests de pénétration réguliers pour identifier les failles.', 'security', ARRAY['sécurité', 'tests', 'pénétration', 'réguliers', 'failles'], 10),
('Puis-je avoir une protection des APIs ?', 'Oui, nos APIs sont protégées par authentification, taux limité et validation des entrées.', 'security', ARRAY['protection', 'apis', 'authentification', 'taux limité', 'validation'], 10),
('Comment fonctionne la sécurité des conteneurs ?', 'Nos conteneurs sont scannés pour les vulnérabilités et isolés les uns des autres.', 'security', ARRAY['sécurité', 'conteneurs', 'scannés', 'vulnérabilités', 'isolés'], 10),
('Puis-je avoir une protection des réseaux sociaux ?', 'Oui, les intégrations réseaux sociaux utilisent OAuth2 sécurisé.', 'security', ARRAY['protection', 'réseaux sociaux', 'oauth2', 'sécurisé', 'intégrations'], 10),
('Comment fonctionne la sécurité des notifications ?', 'Les notifications ne contiennent pas de données sensibles et sont chiffrées.', 'security', ARRAY['sécurité', 'notifications', 'données sensibles', 'chiffrées', 'contiennent'], 10),
('Puis-je avoir une protection des fichiers temporaires ?', 'Oui, les fichiers temporaires sont supprimés automatiquement après traitement.', 'security', ARRAY['protection', 'fichiers temporaires', 'supprimés', 'automatiquement', 'traitement'], 10),
('Comment fonctionne la sécurité des webhooks ?', 'Les webhooks utilisent des signatures HMAC pour vérifier leur authenticité.', 'security', ARRAY['sécurité', 'webhooks', 'signatures', 'hmac', 'authenticité'], 10),
('Puis-je avoir une protection des téléchargements ?', 'Oui, les téléchargements sont scannés et limités en taille.', 'security', ARRAY['protection', 'téléchargements', 'scannés', 'limités', 'taille'], 10),
('Comment fonctionne la sécurité des formulaires ?', 'Les formulaires utilisent CAPTCHA et validation côté serveur.', 'security', ARRAY['sécurité', 'formulaires', 'captcha', 'validation', 'serveur'], 10);
